1	import React, { useEffect, useLayoutEffect, useRef, useState } from 'react';
2	import clsx from 'clsx';
3	import { animate, motion, useMotionValue, type AnimationPlaybackControls } from 'framer-motion';
4	import styles from './TopRightMenu.module.scss';
5	
6	// Même tempo que la barre d'outils de la Sidebar au changement d'espace
7	// (CONTAINER_RESHAPE_DURATION = 1.1 s, immobile pendant les 45 % premiers, même courbe). Le
8	// déplacement se fait ensuite en L, un axe après l'autre, jamais en diagonale :
9	//  - vers la Prévisualisation : vers la gauche, puis vers le haut ;
10	//  - retour : vers le bas, puis vers la droite.
