131	  /**
132	   * Joue le rideau "APEX / <espace>" (voir SpaceTransitionOverlay) puis exécute `onCovered`
133	   * une fois l'écran masqué — c'est là, et pas avant, que le vrai changement d'onglet doit
134	   * avoir lieu pour ne jamais être visible pendant la transition. Mesure aussi la forme
135	   * actuelle du conteneur d'outils juste avant : quel que soit le mode de départ (slicer,
136	   * prévisualisation ou modélisation), c'est de là que doit partir l'animation de
137	   * déformation vers le mode suivant — jamais une valeur figée valable pour un seul sens.
138	   */
139	  const playSpaceTransition = (space: keyof typeof SPACE_LABELS, onCovered: () => void) => {
140	    const label = SPACE_LABELS[space];
141	    const sound = SPACE_SOUNDS[space];
142	    if (sound) playUiSound(sound);
143	    if (bottomToolbarRef.current) {
144	      const rect = bottomToolbarRef.current.getBoundingClientRect();
145	      const computedRadius = parseFloat(getComputedStyle(bottomToolbarRef.current).borderTopLeftRadius) || 22;
146	      // `x`/`y` ne sont pas lisibles depuis le DOM (ce sont des translate posés par
147	      // framer-motion, pas une position absolue) : on reprend ceux du mode qu'on est en
148	      // train de quitter, calculés par la même table que `targetGeometry` ci-dessous.
149	      setFromGeometry({
150	        x: targetGeometry.x,
151	        y: targetGeometry.y,
152	        width: rect.width,
153	        height: rect.height,
154	        borderRadius: computedRadius,
155	      });
156	    }
157	    window.dispatchEvent(new CustomEvent('apex-space-transition', { detail: { label, onCovered } }));
158	  };
